from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_day, points) for pending earnings
        self._pending = {}
        # customer -> total currently spendable points
        self._available = {}

    def _mature(self, customer: str, day: date) -> None:
        """Move any pending points whose availability day has arrived
        (i.e., available from purchase day + 14 days) into available balance."""
        pending = self._pending.get(customer)
        if not pending:
            return
        still_pending = []
        matured = 0
        for available_day, pts in pending:
            if available_day <= day:
                matured += pts
            else:
                still_pending.append((available_day, pts))
        if matured:
            self._available[customer] = self._available.get(customer, 0) + matured
        if still_pending:
            self._pending[customer] = still_pending
        else:
            self._pending.pop(customer, None)

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount // 10)
        if points > 0:
            available_day = day + timedelta(days=14)
            self._pending.setdefault(customer, []).append((available_day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        self._mature(customer, day)
        return self._available.get(customer, 0)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0:
            raise ValueError("Redeemed points must be positive")
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")
        self._mature(customer, day)
        current = self._available.get(customer, 0)
        if points > current:
            raise ValueError("Insufficient points balance")
        self._available[customer] = current - points
